# ml_adjust.py - Roots of Tomorrow ML hook for the rotation engine (generated by Notebook B v2)
# Adjusts the 0-100 GAEZ suitability index for a farmer-reported soil pH. Texture is NOT adjusted here
# (the model's texture effects are unconstrained and were not validated); the engine keeps its texture rules.
import json, numpy as np, pandas as pd, joblib
PH_LOW, PH_HIGH = 6.0, 7.5

class SoilAdjuster:
    def __init__(self, model_path, meta_path):
        self.model = joblib.load(model_path)
        self.meta = json.load(open(meta_path))
        self.feats = self.meta['features']

    def _frame(self, base_features, crops, mgmt, ph):
        rows = []
        for c in crops:
            r = {f: base_features.get(f, np.nan) for f in self.feats}
            r['soil_ph_acid'], r['soil_ph_alk'] = max(PH_LOW - ph, 0.0), max(ph - PH_HIGH, 0.0)
            r['crop'], r['mgmt'] = c, mgmt
            rows.append(r)
        return pd.DataFrame(rows)[self.feats + ['crop', 'mgmt']]

    def ph_delta(self, base_features, crops, mgmt, satellite_ph, farmer_ph):
        # base_features: dict with the model features (SoilGrids soil, NASA POWER climate, abs_lat, nb* GAEZ neighbours).
        # Returns {crop: change in suitability index (<= 0 when the farmer's pH is further from 6.0-7.5 than the satellite pH)}.
        if farmer_ph is None or satellite_ph is None:
            return {c: 0.0 for c in crops}
        p = lambda ph: np.clip(self.model.predict(self._frame(base_features, crops, mgmt, float(ph))), 0, 100)
        return {c: float(v) for c, v in zip(crops, p(farmer_ph) - p(satellite_ph))}
